add_action( 'woocommerce_product_query', 'perfectpixel_in_stock_first_flag' );
add_filter( 'posts_clauses', 'perfectpixel_in_stock_first_clauses', 30, 2 );

function perfectpixel_in_stock_first_flag( $q ) {
	$q->set( 'perfectpixel_in_stock_first', 1 );
}

function perfectpixel_in_stock_first_clauses( $clauses, $query ) {
	global $wpdb;
	if ( ! $query->get( 'perfectpixel_in_stock_first' ) ) {
		return $clauses;
	}
	$clauses['join']   .= " LEFT JOIN {$wpdb->prefix}wc_product_meta_lookup pp_stock ON pp_stock.product_id = {$wpdb->posts}.ID";
	$clauses['orderby'] = "( pp_stock.stock_status = 'outofstock' ) ASC" . ( $clauses['orderby'] ? ', ' . $clauses['orderby'] : '' );
	return $clauses;
}
